//! The Rust half of the `flagship/pq-session/v1` vectors
//! (packages/protocol/test-vectors/pq-session/vectors.json, generated by
//! tools/pq-session-vectors.ts). Every message and key must come out byte for
//! byte; every refusal must carry the TypeScript code.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]

use flagship_crypto::HybridSigningKey;
use flagship_crypto::session::{
    Accept, Finish, Hello, Initiator, InitiatorRole, SessionError, accept, open_record, seal_record,
};
use flagship_crypto::trust::{
    BindingWire, Expectation, Role, VerifiedBinding, hex, verify_binding,
};
use flagship_protocol::parse::parse_lower_hex;
use serde_json::Value;
use std::path::PathBuf;

fn vectors() -> Value {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../packages/protocol/test-vectors/pq-session/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

struct Party {
    name: String,
    role: String,
    subject: String,
    key: HybridSigningKey,
    binding: VerifiedBinding,
}

fn arr<const N: usize>(s: &str) -> [u8; N] {
    <[u8; N]>::try_from(parse_lower_hex(s, N, N).unwrap().as_slice()).unwrap()
}

fn parties(v: &Value) -> Vec<Party> {
    let now = v["now"].as_u64().unwrap();
    v["parties"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| {
            let b = &p["binding"];
            let w = BindingWire {
                version: b["v"].as_u64().unwrap() as u8,
                role: b["role"].as_str().unwrap(),
                subject_id: b["subjectId"].as_str().unwrap(),
                ed25519_pub_hex: b["ed25519PubHex"].as_str().unwrap(),
                mldsa_pub_hex: b["mldsaPubHex"].as_str().unwrap(),
                issued_at: b["issuedAt"].as_u64().unwrap(),
                signature_hex: b["signature"].as_str().unwrap(),
            };
            let e = Expectation {
                role: Role::parse(w.role).unwrap(),
                subject_id: w.subject_id,
                ed25519_pub_hex: w.ed25519_pub_hex,
                mldsa_pub_hex: None,
                now,
                min_issued_at: None,
            };
            let binding = verify_binding(&w, &e).unwrap();
            let key = HybridSigningKey::from_seeds(
                &arr::<32>(p["edSeedHex"].as_str().unwrap()),
                &arr::<32>(p["mldsaSeedHex"].as_str().unwrap()),
            )
            .unwrap();
            assert_eq!(
                hex(&binding.hybrid_key().key_id()),
                p["keyIdHex"].as_str().unwrap()
            );
            Party {
                name: p["name"].as_str().unwrap().to_owned(),
                role: p["role"].as_str().unwrap().to_owned(),
                subject: p["subject"].as_str().unwrap().to_owned(),
                key,
                binding,
            }
        })
        .collect()
}

const HELLO_KEYS: [&str; 9] = [
    "ephemeralPub",
    "initiatorKeyId",
    "initiatorRole",
    "initiatorSubject",
    "issuedAt",
    "nonce",
    "responder",
    "responderKeyId",
    "v",
];

fn keys_are(v: &Value, want: &[&str]) -> bool {
    let Some(o) = v.as_object() else { return false };
    let mut k: Vec<&str> = o.keys().map(String::as_str).collect();
    k.sort_unstable();
    k == want && v["v"].as_u64() == Some(1)
}

fn hx(v: &Value, k: &str, n: usize) -> Result<Vec<u8>, SessionError> {
    parse_lower_hex(v[k].as_str().ok_or(SessionError::Malformed)?, n, n)
        .map_err(|_| SessionError::Malformed)
}

fn fixed<const N: usize>(v: &Value, k: &str) -> Result<[u8; N], SessionError> {
    <[u8; N]>::try_from(hx(v, k, N)?.as_slice()).map_err(|_| SessionError::Malformed)
}

/// The JSON-level decoding TypeScript does before the typed checks.
fn hello(v: &Value) -> Result<Hello, SessionError> {
    if !keys_are(v, &HELLO_KEYS) {
        return Err(SessionError::Malformed);
    }
    Ok(Hello {
        responder: v["responder"]
            .as_str()
            .ok_or(SessionError::Malformed)?
            .to_owned(),
        initiator_role: InitiatorRole::parse(
            v["initiatorRole"].as_str().ok_or(SessionError::Malformed)?,
        )?,
        initiator_subject: v["initiatorSubject"]
            .as_str()
            .ok_or(SessionError::Malformed)?
            .to_owned(),
        initiator_key_id: fixed(v, "initiatorKeyId")?,
        responder_key_id: fixed(v, "responderKeyId")?,
        ephemeral_pub: hx(v, "ephemeralPub", 1216)?,
        nonce: fixed(v, "nonce")?,
        issued_at: v["issuedAt"].as_u64().ok_or(SessionError::Malformed)?,
    })
}

fn accept_of(v: &Value) -> Result<Accept, SessionError> {
    if !keys_are(
        v,
        &["confirm", "enc", "issuedAt", "nonce", "signature", "v"],
    ) {
        return Err(SessionError::Malformed);
    }
    Ok(Accept {
        enc: hx(v, "enc", 1120)?,
        nonce: fixed(v, "nonce")?,
        issued_at: v["issuedAt"].as_u64().ok_or(SessionError::Malformed)?,
        signature: hx(v, "signature", 3373)?,
        confirm: fixed(v, "confirm")?,
    })
}

fn finish_of(v: &Value) -> Result<Finish, SessionError> {
    if !keys_are(v, &["confirm", "signature", "v"]) {
        return Err(SessionError::Malformed);
    }
    Ok(Finish {
        signature: hx(v, "signature", 3373)?,
        confirm: fixed(v, "confirm")?,
    })
}

struct World {
    v: Value,
    ps: Vec<Party>,
    now: u64,
}

impl World {
    fn new() -> Self {
        let v = vectors();
        let ps = parties(&v);
        let now = v["now"].as_u64().unwrap();
        Self { v, ps, now }
    }
    fn party(&self, n: &str) -> &Party {
        self.ps.iter().find(|p| p.name == n).unwrap()
    }
    fn trusted(&self) -> Vec<&Party> {
        self.v["responderTrusts"]
            .as_array()
            .unwrap()
            .iter()
            .map(|n| self.party(n.as_str().unwrap()))
            .collect()
    }
    fn r(&self, k: &str) -> Vec<u8> {
        parse_lower_hex(self.v["randomness"][k].as_str().unwrap(), 0, 1 << 10).unwrap()
    }
    fn start(&self, t: &Value) -> Initiator {
        let ini = self.party(t["initiator"].as_str().unwrap());
        let role = InitiatorRole::parse(&ini.role).unwrap();
        let seed = <[u8; 32]>::try_from(self.r("ephemeralSeedHex").as_slice()).unwrap();
        let nonce = <[u8; 32]>::try_from(self.r("helloNonceHex").as_slice()).unwrap();
        Initiator::start(
            &self.party("box").binding,
            role,
            &ini.binding,
            self.now,
            Some((seed, nonce)),
        )
        .unwrap()
    }
    fn accept(
        &self,
        h: &Value,
    ) -> Result<(Accept, flagship_crypto::session::Pending), SessionError> {
        let h = hello(h)?;
        let trusted = self.trusted();
        let lookup = |role: InitiatorRole, subject: &str, kid: &[u8; 32]| {
            trusted
                .iter()
                .find(|p| {
                    p.role == role.as_str()
                        && p.subject == subject
                        && &p.binding.hybrid_key().key_id() == kid
                })
                .map(|p| p.binding.clone())
        };
        let boxp = self.party("box");
        let sign = |purpose: &str, payload: &[u8]| {
            boxp.key
                .sign_deterministic(purpose, payload)
                .map_err(|_| SessionError::BadSignature)
        };
        let e = <[u8; 64]>::try_from(self.r("encapsulationHex").as_slice()).unwrap();
        let n = <[u8; 32]>::try_from(self.r("acceptNonceHex").as_slice()).unwrap();
        accept(
            &h,
            &boxp.binding,
            &lookup,
            self.now + 100,
            &sign,
            Some((e, n)),
        )
    }
}

fn accept_json(a: &Accept) -> Value {
    serde_json::json!({ "v": 1, "enc": hex(&a.enc), "nonce": hex(&a.nonce), "issuedAt": a.issued_at, "signature": hex(&a.signature), "confirm": hex(&a.confirm) })
}

#[test]
fn transcripts_reproduce_byte_for_byte() {
    let w = World::new();
    for t in w.v["transcripts"].as_array().unwrap() {
        let ini = w.party(t["initiator"].as_str().unwrap());
        let st = w.start(t);
        assert_eq!(hello(&t["hello"]).unwrap(), *st.hello());
        assert_eq!(
            hex(&st.hello().to_bytes().unwrap()),
            t["helloBytesHex"].as_str().unwrap()
        );
        let (a, pending) = w.accept(&t["hello"]).unwrap();
        assert_eq!(accept_json(&a), t["accept"]);
        let sign = |purpose: &str, payload: &[u8]| {
            ini.key
                .sign_deterministic(purpose, payload)
                .map_err(|_| SessionError::BadSignature)
        };
        let (f, mut ichan) = st.finish(&a, w.now + 200, &sign).unwrap();
        assert_eq!(
            hex(&f.signature),
            t["finish"]["signature"].as_str().unwrap()
        );
        assert_eq!(hex(&f.confirm), t["finish"]["confirm"].as_str().unwrap());
        let mut rchan = pending.complete(&f, w.now + 300).unwrap();
        let k = &t["keys"];
        assert_eq!(hex(ichan.session_id()), k["sessionIdHex"].as_str().unwrap());
        assert_eq!(hex(rchan.session_id()), k["sessionIdHex"].as_str().unwrap());
        let sid = arr::<32>(k["sessionIdHex"].as_str().unwrap());
        for r in t["records"].as_array().unwrap() {
            let dir = u8::try_from(r["dir"].as_u64().unwrap()).unwrap();
            let key = arr::<32>(
                k[if dir == 1 {
                    "initiatorToResponderHex"
                } else {
                    "responderToInitiatorHex"
                }]
                .as_str()
                .unwrap(),
            );
            let pt = parse_lower_hex(r["plaintextHex"].as_str().unwrap(), 0, 1 << 20).unwrap();
            let seq = r["seq"].as_u64().unwrap();
            assert_eq!(
                hex(&seal_record(&key, &sid, dir, seq, &pt).unwrap()),
                r["recordHex"].as_str().unwrap()
            );
            let rec = parse_lower_hex(r["recordHex"].as_str().unwrap(), 0, 1 << 20).unwrap();
            let (s, o) = open_record(&key, &sid, dir, &rec).unwrap();
            assert_eq!((s, o.as_slice()), (seq, pt.as_slice()));
        }
        let recs = t["records"].as_array().unwrap();
        let rec =
            |i: usize| parse_lower_hex(recs[i]["recordHex"].as_str().unwrap(), 0, 1 << 20).unwrap();
        rchan.open_request(&rec(1), w.now + 400).unwrap();
        rchan.open_request(&rec(0), w.now + 400).unwrap();
        assert_eq!(
            hex(&ichan.open_response(1, &rec(2)).unwrap()),
            recs[2]["plaintextHex"].as_str().unwrap()
        );
        let (seq, _) = ichan.seal_request(b"x", w.now + 500).unwrap();
        assert_eq!(seq, 0);
    }
}

fn code<T>(r: Result<T, SessionError>) -> &'static str {
    match r {
        Ok(_) => "ok",
        Err(e) => e.code(),
    }
}

#[test]
fn invalid_hellos_accepts_finishes_and_records() {
    let w = World::new();
    let t0 = &w.v["transcripts"][0];
    let phone = w.party("phone");
    let sign = |purpose: &str, payload: &[u8]| {
        phone
            .key
            .sign_deterministic(purpose, payload)
            .map_err(|_| SessionError::BadSignature)
    };
    for c in w.v["invalid"]["hello"].as_array().unwrap() {
        assert_eq!(
            code(w.accept(&c["hello"])),
            c["expect"].as_str().unwrap(),
            "hello {}",
            c["name"]
        );
    }
    for c in w.v["invalid"]["accept"].as_array().unwrap() {
        let got = accept_of(&c["accept"])
            .and_then(|a| w.start(t0).finish(&a, w.now + 200, &sign).map(|_| ()));
        assert_eq!(
            code(got),
            c["expect"].as_str().unwrap(),
            "accept {}",
            c["name"]
        );
    }
    for c in w.v["invalid"]["finish"].as_array().unwrap() {
        let (_, pending) = w.accept(&t0["hello"]).unwrap();
        let got =
            finish_of(&c["finish"]).and_then(|f| pending.complete(&f, w.now + 300).map(|_| ()));
        assert_eq!(
            code(got),
            c["expect"].as_str().unwrap(),
            "finish {}",
            c["name"]
        );
    }
    for c in w.v["invalid"]["records"].as_array().unwrap() {
        let (a, pending) = w.accept(&t0["hello"]).unwrap();
        let (f, ichan) = w.start(t0).finish(&a, w.now + 200, &sign).unwrap();
        let mut rchan = pending.complete(&f, w.now + 300).unwrap();
        let got = if c["side"] == "responder" {
            c["sequence"].as_array().unwrap().iter().try_for_each(|r| {
                rchan
                    .open_request(
                        &parse_lower_hex(r.as_str().unwrap(), 0, 1 << 20).unwrap(),
                        w.now + 400,
                    )
                    .map(|_| ())
            })
        } else {
            ichan
                .open_response(
                    c["expectSeq"].as_u64().unwrap(),
                    &parse_lower_hex(c["record"].as_str().unwrap(), 0, 1 << 20).unwrap(),
                )
                .map(|_| ())
        };
        assert_eq!(
            code(got),
            c["expect"].as_str().unwrap(),
            "record {}",
            c["name"]
        );
    }
}

#[test]
fn idle_sessions_expire() {
    let w = World::new();
    let t0 = &w.v["transcripts"][0];
    let phone = w.party("phone");
    let sign = |purpose: &str, payload: &[u8]| {
        phone
            .key
            .sign_deterministic(purpose, payload)
            .map_err(|_| SessionError::BadSignature)
    };
    let (a, pending) = w.accept(&t0["hello"]).unwrap();
    let (f, _) = w.start(t0).finish(&a, w.now + 200, &sign).unwrap();
    let mut r = pending.complete(&f, w.now + 300).unwrap();
    let rec = parse_lower_hex(t0["records"][0]["recordHex"].as_str().unwrap(), 0, 1 << 20).unwrap();
    assert_eq!(
        code(r.open_request(&rec, w.now + 300 + 16 * 60_000)),
        "session-expired"
    );
}
